import json, glob, os
root = '/root/projects/open_source/zero/B96DF826-4BB2-4B62-97AB-6D84254C53D7/Scenario-8/alerts'
filtered = []
for path in sorted(glob.glob(os.path.join(root, '*.json'))):
    with open(path) as f:
        data = json.load(f)
        for alert in data:
            if isinstance(alert, dict):
                ns = alert.get('labels', {}).get('namespace')
                if ns == 'otel-demo':
                    filtered.append((path, alert))
print('Total otel-demo alerts:', len(filtered))
if filtered:
    names = sorted({a['labels']['alertname'] for _, a in filtered})
    print('Alert names:', names)
    for p,a in filtered[:10]:
        print('File', os.path.basename(p), 'alert', a['labels']['alertname'], 'severity', a['labels'].get('severity'))
PY"],"timeout_ms":100000,"workdir":"/"}

